    // s\u00fcre dolunca: patlama dalgalar\u0131\n    if (boom && t - boom < 3200) { const k = (t - boom) / 3200; c.save(); for (let i = 0; i < 3; i++) { const kk = Math.max(0, k * 1.4 - i * .18); c.globalAlpha = Math.max(0, 1 - kk) * .8; c.strokeStyle = i % 2 ? '#3a8aff' : '#ff3a4a'; c.lineWidth = (10 - i * 2) * u; c.beginPath(); c.arc(cxX, cyX, xs * 1.2 + kk * Math.max(W, H) * .8, 0, 7); c.stroke(); } c.globalAlpha = Math.max(0, .55 - k); c.fillStyle = '#fff'; c.fillRect(0, 0, W, H); c.restore(); }\n  }\n  const BOLT = [[.5, -.02], [.56, .12], [.46, .26], [.6, .42], [.47, .56], [.58, .72], [.45, .86], [.52, 1.02]];\n  function bolt(W, H) { const sh = (W < H * 1.1 || W < 950) ? .1 : 0; return BOLT.map(([x, y]) => [(x + sh) * W, y * H]); }\n  function drawScene(c, W, H, t, dt) {\n    const u = H / 540, B = bolt(W, H), pulse = 0.5 + 0.5 * Math.sin(t / 260);\n    // k\u0131rm\u0131z\u0131 (sol) / mavi (sa\u011f) zemin, y\u0131ld\u0131r\u0131mla b\u00f6l\u00fcnm\u00fc\u015f\n    c.save(); c.beginPath(); c.moveTo(0, 0); for (const p of B) c.lineTo(p[0], p[1]); c.lineTo(0, H); c.closePath(); c.clip();\n    let g1 = c.createLinearGradient(0, 0, W * .5, H); g1.addColorStop(0, '#3a0408'); g1.addColorStop(.5, '#a8101c'); g1.addColorStop(1, '#ff3a3a'); c.fillStyle = g1; c.fillRect(0, 0, W, H);\n    c.fillStyle = 'rgba(255,255,255,.07)'; for (let y = 0; y < H; y += 18 * u) for (let x = (y / (18 * u)) % 2 ? 9 * u : 0; x < W * .62; x += 18 * u) { c.beginPath(); c.arc(x, y, 2.4 * u * (1 - y / H * .6), 0, 7); c.fill(); }\n    c.restore();\n    c.save(); c.beginPath(); c.moveTo(W, 0); for (const p of B) c.lineTo(p[0], p[1]); c.lineTo(W, H); c.closePath(); c.clip();\n    let g2 = c.createLinearGradient(W, 0, W * .5, H); g2.addColorStop(0, '#03103a'); g2.addColorStop(.5, '#0c3aa8'); g2.addColorStop(1, '#3a8aff'); c.fillStyle = g2; c.fillRect(0, 0, W, H);\n    c.fillStyle = 'rgba(255,255,255,.07)'; for (let y = 0; y < H; y += 18 * u) for (let x = W * .38 + ((y / (18 * u)) % 2 ? 9 * u : 0); x < W; x += 18 * u) { c.beginPath(); c.arc(x, y, 2.4 * u * (1 - y / H * .6), 0, 7); c.fill(); }\n    c.restore();\n    // h\u0131z \u00e7izgileri\n    c.save(); c.globalAlpha = .1; c.lineWidth = 2 * u; for (let i = 0; i < 26; i++) { const a = i / 26 * 6.283 + t / 9000, r0 = Math.min(W, H) * .22, r1 = Math.max(W, H); c.strokeStyle = Math.cos(a) < 0 ? '#ff8a8a' : '#8ab8ff'; c.beginPath(); c.moveTo(W * .5 + Math.cos(a) * r0, H * .5 + Math.sin(a) * r0); c.lineTo(W * .5 + Math.cos(a) * r1, H * .5 + Math.sin(a) * r1); c.stroke(); } c.restore();\n    // dev silik isimler\n    c.save(); c.font = '900 ' + Math.round(H * .3) + 'px sans-serif'; c.textAlign = 'center'; c.fillStyle = 'rgba(255,255,255,.07)'; c.fillText('MERT', W * .26, H * .62); c.fillText('EREN', W * .76, H * .62); c.restore();\n    // karakterler\n    const lowHalf = W < H * 1.1 || W < 950, uu = Math.min(H * .082, W * (lowHalf ? .062 : .06));\n    person(c, 'mert', W * (lowHalf ? .5 : .405), H * .87, uu, t, 0); person(c, 'eren', W * (lowHalf ? .86 : .78), H * .87, uu, t, 1.7);\n    // y\u0131ld\u0131r\u0131m \u00e7izgisi: d\u0131\u015f par\u0131lt\u0131 + beyaz \u00e7ekirdek\n    c.save(); c.lineJoin = 'miter'; c.lineCap = 'round'; for (const [w, col, bl] of [[22 * u, 'rgba(255,255,255,.18)', 40 * u], [11 * u, '#ffffff', 30 * u], [4 * u, '#fff8c8', 0]]) { c.strokeStyle = col; c.lineWidth = w; c.shadowColor = '#fff'; c.shadowBlur = bl * (0.7 + 0.5 * pulse); c.beginPath(); B.forEach((p, i) => i ? c.lineTo(p[0], p[1]) : c.moveTo(p[0], p[1])); c.stroke(); } c.restore();\n    // ortada X\n    const cx = W * ((W < H * 1.1 || W < 950) ? .62 : .52), cy = H * .5, xs = Math.min(W, H) * (.13 + .008 * pulse); c.save(); c.translate(cx, cy); c.rotate(Math.sin(t / 900) * .05); c.shadowColor = '#fff'; c.shadowBlur = 28 * u; c.lineCap = 'round'; c.lineWidth = xs * .34; c.strokeStyle = '#fff'; c.beginPath(); c.moveTo(-xs, -xs); c.lineTo(xs, xs); c.moveTo(xs, -xs); c.lineTo(-xs, xs); c.stroke(); c.shadowBlur = 0; c.lineWidth = xs * .16; c.strokeStyle = '#ff3a3a'; c.beginPath(); c.moveTo(-xs, -xs); c.lineTo(xs * .02, xs * .02); c.moveTo(-xs, xs); c.lineTo(xs * .02, -xs * .02); c.stroke(); c.strokeStyle = '#3a8aff'; c.beginPath(); c.moveTo(xs, xs); c.lineTo(-xs * .02, -xs * .02); c.moveTo(xs, -xs); c.lineTo(-xs * .02, xs * .02); c.stroke(); c.restore();\n    drawTimer(c, W, H, t, u, lowHalf, cx, cy, xs);\n    // par\u00e7ac\u0131klar (k\u0131v\u0131lc\u0131m / y\u0131ld\u0131z)\n    if (!PART.length) for (let i = 0; i < 46; i++) PART.push({ x: rn() * W, y: rn() * H, v: 20 + rn() * 60, s: 2 + rn() * 5, p: rn() * 7, k: i % 3 });\n    for (const q of PART) { q.y -= q.v * dt; q.x += Math.sin(t / 700 + q.p) * 14 * dt; if (q.y < -10) { q.y = H + 10; q.x = rn() * W; } const left = q.x < W * .5; c.fillStyle = left ? 'rgba(255,170,150,.85)' : 'rgba(150,200,255,.85)'; c.globalAlpha = .5 + .5 * Math.sin(t / 300 + q.p); if (q.k === 0) { c.beginPath(); c.arc(q.x, q.y, q.s * u, 0, 7); c.fill(); } else { c.save(); c.translate(q.x, q.y); c.rotate(t / 900 + q.p); c.fillRect(-q.s * u, -q.s * u * .25, q.s * u * 2, q.s * u * .5); c.fillRect(-q.s * u * .25, -q.s * u, q.s * u * .5, q.s * u * 2); c.restore(); } c.globalAlpha = 1; }\n    // YAKINDA...\n    c.save(); c.textAlign = 'center'; c.font = '900 ' + Math.round(H * .085) + 'px sans-serif'; const dots = '.'.repeat(1 + Math.floor(t / 450) % 3); c.lineWidth = 6 * u; c.strokeStyle = '#000'; c.lineJoin = 'round'; const tx = W * (lowHalf ? .62 : .52), ty = H * .93; c.strokeText(AT > Date.now() ? 'YAKINDA' + dots : 'BA\u015eLADI!', tx, ty); const tg = c.createLinearGradient(tx - W * .15, 0, tx + W * .15, 0); tg.addColorStop(0, '#ff5a5a'); tg.addColorStop(.5, '#fff'); tg.addColorStop(1, '#5a9aff'); c.fillStyle = tg; c.fillText(AT > Date.now() ? 'YAKINDA' + dots : 'BA\u015eLADI!', tx, ty); c.restore();\n    // \u00fcst/alt \u015ferit\n    c.fillStyle = 'rgba(0,0,0,.35)'; c.fillRect(0, 0, W, 5 * u); c.fillRect(0, H - 5 * u, W, 5 * u);\n  }\n  function frame(t) {\n    raf = requestAnimationFrame(frame);\n    const menu = $('menu'); if (!bgc || !menu || menu.classList.contains('hidden') || !document.body.classList.contains('mx')) return;\n    if (t - lastDraw < (document.body.classList.contains('lowfx') ? 50 : 33)) return; const dt = Math.min(.06, (t - lastT) / 1000 || .03); lastT = t; lastDraw = t;\n    const r = menu.getBoundingClientRect(); if (Math.abs(bg.width - r.width) > 2 || Math.abs(bg.height - r.height) > 2) size();\n    drawScene(bgc, bg.width, bg.height, t, dt);\n  }\n  function size() { if (!bg) return; const r = bg.parentNode.getBoundingClientRect(); bg.width = Math.max(1, r.width | 0); bg.height = Math.max(1, r.height | 0); PART = []; }\n  const fmt = ms => { ms = Math.max(0, ms); const s = Math.floor(ms / 1000); const d = Math.floor(s / 86400); return (d ? d + 'g ' : '') + String(Math.floor(s / 3600) % 24).padStart(2, '0') + ':' + String(Math.floor(s / 60) % 60).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };\n  X.drawLoad = function () { const cv = $('mxLoad'); if (!cv || !X.on()) return; const W = Math.max(2, Math.min(innerWidth, 1280)), H = Math.max(2, Math.round(W * innerHeight / Math.max(1, innerWidth))); cv.width = W; cv.height = H; try { drawScene(cv.getContext('2d'), W, H, 1500, 0.016); const c = cv.getContext('2d'); c.save(); c.textAlign = 'left'; c.font = '900 ' + Math.round(H * 0.06) + 'px sans-serif'; c.fillStyle = '#fff'; c.shadowColor = '#000'; c.shadowBlur = 12; c.fillText('PLAYGROUND D', W * 0.05, H * 0.2); c.restore(); } catch (e) {} };\n  X.apply = function () { document.body.classList.toggle('mx', X.on()); X.drawLoad(); const t = document.querySelector('meta[name=theme-color]'); if (X.on() && t) t.content = '#1a0610'; };\n  function tick() {\n    const bt = $('mxBtn'); if (!bt) return;\n    const menu = $('menu'), hud = $('hud'), vis = e => e && !e.classList.contains('hidden'), inMenu = vis(menu) && !document.querySelector('.modal:not(.hidden)');\n    bt.classList.toggle('hidden', !inMenu); bt.classList.toggle('on', X.on());\n    const left = AT - Date.now(); bt.querySelector('small').textContent = left > 0 ? 'ETK\u0130NL\u0130\u011eE ' + fmt(left) : 'BA\u015eLADI!';\n    const mb = $('mxMus'); mb.style.display = X.on() && inMenu ? '' : 'none'; mb.textContent = enabled ? '\u266a' : '\u2715\u266a';\n    const A = VD.Audio, want = X.on() && !vis(hud) && enabled && (vis(menu) || vis($('lobbyUI')));\n    if (want) { if (A && A.hold) A.hold(true); if (VD.CollabMusic) VD.CollabMusic.stop(); if (VD.Xmas) VD.Xmas.Music.stop(); X.music.start(); } else if (wanted) { X.music.stop(); if (A && A.hold && !(VD.CollabMusic && 0)) A.hold(false); }\n  }\n  X.person = person; // mxr.js (yar\u0131\u015f) ayn\u0131 karakterleri kullan\u0131r\n  X.init = function () {\n    const menu = $('menu'); if (!menu) return;\n    bg = document.createElement('canvas'); bg.id = 'mxBg'; menu.insertBefore(bg, menu.firstChild); bgc = bg.getContext('2d'); size(); addEventListener('resize', () => { size(); X.drawLoad(); });\n    const bt = document.createElement('div'); bt.id = 'mxBtn'; bt.className = 'hidden'; bt.innerHTML = '<button type=\"button\" id=\"mxTog\"><b>MERT<i>\u2715</i>EREN</b><small>YAKINDA...</small></button><button type=\"button\" id=\"mxMus\" title=\"M\u00fczik\">\u266a</button>'; document.body.appendChild(bt);\n    $('mxTog').onclick = ev => { ev.stopPropagation(); lput(KEY, X.on() ? 'off' : 'on'); X.apply(); X.music.unlock(); tick(); };\n    $('mxMus').onclick = ev => { ev.stopPropagation(); X.music.setEnabled(!enabled); tick(); };\n    bt.addEventListener('pointerdown', ev => ev.stopPropagation());\n    const unl = () => { X.music.unlock(); tick(); }; document.addEventListener('pointerdown', unl); document.addEventListener('keydown', unl);\n    X.apply(); tick(); setInterval(tick, 700); raf = requestAnimationFrame(frame);\n  };\n  if (document.body && $('menu')) X.init(); else document.addEventListener('DOMContentLoaded', X.init);\n})();\n</script>\n<script>/* MERT \u00d7 EREN \u2014 1. HAFTA: \u0130zlenebilir sim\u00fclasyon yar\u0131\u015f\u0131.\n   18 Kas\u0131m 15:00 (TR): Mert ve Eren botlar\u0131 3 kez yar\u0131\u015f\u0131r; herkes ayn\u0131 anda, ayn\u0131 yar\u0131\u015f\u0131 izler (sunucu gerekmez:\n   sonu\u00e7 sabit tohumdan \u00fcretilir, her cihazda birebir ayn\u0131 \u00e7\u0131kar). 3 yar\u0131\u015f bitince \u00e7o\u011funlu\u011fu kazanan 1 puan al\u0131r\n   ve kazanan\u0131n avatar\u0131 sevin\u00e7 hareketi yapar. Renkler tema ile ayn\u0131: Mert k\u0131rm\u0131z\u0131, Eren mavi.\n   Sonraki haftalar: WEEKS dizisine yeni sat\u0131r eklemek yeterli. */\n(function () {\n  'use strict';\n  const VD = window.VD = window.VD || {}, M = VD.Mxr = {};\n  const $ = id => document.getElementById(id);\n  const demo = /[?&]mxr=demo/.test(location.search); // deneme: 4 sn sonra ba\u015flar\n  const START = demo ? Date.now() + 4000 : Date.UTC(2026, 10, 18, 12, 0, 0);  // 18 Kas\u0131m 15:00 TR\n  const END = demo ? START + 864e5 : Date.UTC(2027, 0, 11, 12, 0, 0);          // 11 Ocak 15:00 TR\n  const WEEKS = [{ at: START, seed: 42 }];                                  // yeni hafta = yeni sat\u0131r\n  const NAME = ['MERT', 'EREN'], TAG = ['@Ad_bu41', '@koftepapates'], COL = ['#ff3a4a', '#3a8aff'], COLD = ['#7a0a14', '#0a2a7a'];\n  const lget = k => { try { return localStorage.getItem(k); } catch (e) { return null; } }, lput = (k, v) => { try { localStorage.setItem(k, v); } catch (e) {} };\n  const sget = k => { try { return sessionStorage.getItem(k); } catch (e) { return null; } }, sput = (k, v) => { try { sessionStorage.setItem(k, v); } catch (e) {} };\n\n  /* ---------- deterministik sim\u00fclasyon (yaln\u0131zca + \u2212 \u00d7 \u00f7, her cihazda ayn\u0131 sonu\u00e7) ---------- */\n  function mul(seed) { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }\n  const L = 1200, DT = 1 / 30, clamp = (v, a, b) => Math.max(a, Math.min(b, v));\n  function sim(seed) {\n    const r = mul(seed), objs = [[], []];\n    for (let i = 0; i < 2; i++) { let x = 110 + r() * 60; while (x < L - 90) { objs[i].push({ x, k: r() < .5 ? 'boost' : 'trip', d: false }); x += 120 + r() * 110; } }\n    const S = [{ p: 0, v: 0, w: 0, b: 0, s: 0 }, { p: 0, v: 0, w: 0, b: 0, s: 0 }], P = [[0], [0]], ev = [], fin = [null, null];\n    for (let k = 1; k < 2700 && (fin[0] === null || fin[1] === null); k++) {\n      const t = k * DT;\n      for (let i = 0; i < 2; i++) {\n        const s = S[i], o = S[1 - i];\n        s.w = clamp(s.w + (r() - .5) * 2.6 * DT - s.w * .6 * DT, -.22, .22);\n        let m = 1 + s.w + clamp((o.p - s.p) / 420, -.12, .12);\n        if (s.b > 0) { m *= 1.55; s.b -= DT; } if (s.s > 0) { m *= .4; s.s -= DT; }\n        if (fin[i] !== null) m = 0;\n        s.v += (40 * m - s.v) * Math.min(1, 4 * DT); s.p += s.v * DT;\n        for (const o2 of objs[i]) if (!o2.d && s.p >= o2.x) { o2.d = true; if (o2.k === 'boost') s.b = 1.3; else s.s = .9; ev.push({ t, i, k: o2.k }); }\n        if (fin[i] === null && s.p >= L) fin[i] = t - (s.p - L) / Math.max(1, s.v);\n        P[i].push(s.p);\n      }\n    }\n    if (fin[0] === null) fin[0] = 99; if (fin[1] === null) fin[1] = 99;\n    return { P, ev, fin, win: fin[0] < fin[1] ? 0 : 1, dur: Math.min(fin[0], fin[1]), end: Math.max(fin[0], fin[1]), objs: objs.map(a => a.map(o => ({ x: o.x, k: o.k }))) };\n  }\n  const at = (arr, t) => { const f = clamp(t / DT, 0, arr.length - 1), i = Math.floor(f); return arr[i] + (arr[Math.min(arr.length - 1, i + 1)] - arr[i]) * (f - i); };\n\n  /* ---------- hafta zaman \u00e7izelgesi ---------- */\n  const INTRO = 9, VOTE = 15, CD = 4, TAIL = 2.5, RES = 5, TALLY = 6, CEL = 16;\n  function build(w) {\n    const races = [1, 2, 3].map(n => sim(w.seed * 10 + n)); let t = INTRO + VOTE; const seg = [];\n    races.forEach((rc, i) => { seg.push({ i, cd: t, go: t + CD, fin: t + CD + rc.dur, end: t + CD + rc.dur + TAIL, res: t + CD + rc.dur + TAIL + RES }); t += CD + rc.dur + TAIL + RES; });\n    const wins = [0, 0]; races.forEach(r => wins[r.win]++);\n    const win = wins[0] > wins[1] ? 0 : 1;\n    return { races, seg, wins, win, max: 3, vote: INTRO, tally: t, cel: t + TALLY, total: t + TALLY + CEL };\n  }\n  const W1 = WEEKS.map(build);\n  const totals = () => { const p = [0, 0]; W1.forEach((w, i) => { if (Date.now() >= WEEKS[i].at + w.total * 1000) p[w.win]++; }); return p; };\n\n  /* ---------- tahmin oyu (cihazda saklan\u0131r; sunucu gerekmez) ---------- */\n  const vkey = i => 'vd_mxr_vote' + i, myVote = i => { const v = lget(vkey(i)); return v === '0' ? 0 : v === '1' ? 1 : -1; };\n  let hit = [];\n  M.vote = k => { if (mode === 'live' || mode === 'replay') { if (myVote(wk) < 0 || mode === 'live') lput(vkey(wk), String(k)); } };\n  /* ---------- ses ---------- */\n  let lastCue = '';\n  function sfx(f, d, type, v) { try { const a = VD.Audio && VD.Audio.api && VD.Audio.api(); if (a && a.tone) a.tone(f, d, type || 'square', v || .18); } catch (e) {} }\n  function cue(key, fn) { if (key !== lastCue) { lastCue = key; fn(); } }\n\n  /* ---------- \u00e7izim ---------- */\n  let ov = null, cv = null, cx = null, raf = 0, mode = null, t0 = 0, wk = 0, dpr = 1;\n  const FONT = () => VD.FONT || '\"Bahnschrift\",\"DIN Alternate\",\"Segoe UI Variable Display\",\"Segoe UI\",\"Trebuchet MS\",system-ui,sans-serif';\n  const font = (px, w) => (w || 800) + ' ' + Math.round(px) + 'px ' + FONT();\n  function mix(col, t) { if (col === '#fff') col = '#ffffff'; if (!/^#[0-9a-f]{6}$/i.test(col)) return col; const n = parseInt(col.slice(1), 16), f = v => Math.round(v + (255 - v) * t); return 'rgb(' + f(n >> 16) + ',' + f(n >> 8 & 255) + ',' + f(n & 255) + ')'; }\n  function rr(c, x, y, w, h, r) { c.beginPath(); c.moveTo(x + r, y); c.arcTo(x + w, y, x + w, y + h, r); c.arcTo(x + w, y + h, x, y + h, r); c.arcTo(x, y + h, x, y, r); c.arcTo(x, y, x + w, y, r); c.closePath(); }\n  function txt(c, s, x, y, px, col, o) {\n    o = o || {}; c.save(); c.font = font(px, o.w || (px >= 26 ? 800 : 700)); c.textAlign = o.al || 'center'; c.textBaseline = 'middle';\n    try { c.letterSpacing = ((o.ls != null ? o.ls : (px >= 30 ? .02 : .05)) * px) + 'px'; } catch (e) {}\n    if (o.glow) { c.shadowColor = o.glow; c.shadowBlur = px * .6; c.fillStyle = col; c.fillText(s, x, y); c.shadowBlur = 0; }\n    c.shadowColor = 'rgba(0,0,0,.55)'; c.shadowBlur = px * .2; c.shadowOffsetY = px * .05;\n    let f = col; if (px >= 28 && /^#[0-9a-f]{3,6}$/i.test(col)) { const g = c.createLinearGradient(0, y - px * .5, 0, y + px * .5); g.addColorStop(0, mix(col, .6)); g.addColorStop(.6, col === '#fff' ? '#d4dcff' : col); g.addColorStop(1, col === '#fff' ? '#aab6ff' : col); f = g; }\n    c.fillStyle = f; c.fillText(s, x, y); c.restore();\n  }\n  function bg(c, W, H, tint, tm) {\n    const g = c.createLinearGradient(0, 0, 0, H); g.addColorStop(0, '#0b0818'); g.addColorStop(1, '#17102a'); c.fillStyle = g; c.fillRect(0, 0, W, H);\n    c.save(); c.globalAlpha = .045; c.strokeStyle = '#fff'; c.lineWidth = 1; for (let x = -H; x < W; x += 46) { c.beginPath(); c.moveTo(x, H); c.lineTo(x + H, 0); c.stroke(); } c.restore();\n    if (tint) { const rg = c.createRadialGradient(W / 2, H * .55, 0, W / 2, H * .55, Math.max(W, H) * .7); rg.addColorStop(0, tint + '66'); rg.addColorStop(1, 'rgba(0,0,0,0)'); c.fillStyle = rg; c.fillRect(0, 0, W, H); }\n    const v = c.createRadialGradient(W / 2, H / 2, Math.min(W, H) * .35, W / 2, H / 2, Math.max(W, H) * .75); v.addColorStop(0, 'rgba(0,0,0,0)'); v.addColorStop(1, 'rgba(0,0,0,.5)'); c.fillStyle = v; c.fillRect(0, 0, W, H);\n  }\n  function runner(c, who, x, base, u, tm, lean, ph) {\n    const P = VD.Mx && VD.Mx.person; if (!P) return;\n    c.save(); c.translate(x, base); c.rotate(lean); c.translate(-x, -base); P(c, who ? 'eren' : 'mert', x, base, u, tm * 2.4, ph); c.restore();\n  }\n  function dots(c, W, H, u, w, upto) { // seri noktalar\u0131\n    const x0 = W / 2 - 60 * u;\n    for (let i = 0; i < (w.max || 3); i++) { const x = W / 2 - ((w.max || 3) - 1) * 30 * u + i * 60 * u, done = i < upto && w.races[i]; c.fillStyle = done ? COL[done.win] : 'rgba(255,255,255,.15)'; c.beginPath(); c.arc(x, H * .115, 11 * u, 0, 7); c.fill(); c.strokeStyle = '#fff'; c.lineWidth = 2 * u; c.stroke(); }\n  }\n  function drawRace(c, W, H, tm, w, sg) {\n    const rc = w.races[sg.i], u = H / 540, k = W / 230, rt = tm - sg.go, run = rt >= 0 && tm < sg.end;\n    const pm = at(rc.P[0], Math.max(0, rt)), pe = at(rc.P[1], Math.max(0, rt)), cam = (pm + pe) / 2;\n    const lane = [H * .5, H * .85], sx = p => W / 2 + (p - cam) * k;\n    bg(c, W, H, null, tm);\n    for (let i = 0; i < 2; i++) { c.fillStyle = i ? 'rgba(60,140,255,.13)' : 'rgba(255,60,70,.13)'; c.fillRect(0, lane[i] - 14 * u, W, 28 * u + (i ? 0 : 0)); c.fillStyle = COL[i] + '33'; c.fillRect(0, lane[i] + 4 * u, W, 5 * u); }\n    // \u00e7izgiler\n    c.fillStyle = 'rgba(255,255,255,.16)'; for (let p = Math.floor((cam - 140) / 20) * 20; p < cam + 140; p += 20) for (let i = 0; i < 2; i++) c.fillRect(sx(p), lane[i] + 14 * u, 3 * u, 12 * u);\n    // engeller / h\u0131zland\u0131r\u0131c\u0131lar\n    for (let i = 0; i < 2; i++) for (const o of rc.objs[i]) { const x = sx(o.x); if (x < -60 || x > W + 60) continue; const y = lane[i] + 2 * u;\n      if (o.k === 'boost') { c.save(); c.shadowColor = '#4af'; c.shadowBlur = 14 * u; c.fillStyle = '#35d0ff'; rr(c, x - 30 * u, y - 4 * u, 60 * u, 12 * u, 5 * u); c.fill(); c.restore(); txt(c, '\u00bb\u00bb', x, y + 2 * u, 14 * u, '#fff'); }\n      else { c.fillStyle = '#ff8a1a'; c.beginPath(); c.moveTo(x - 16 * u, y + 8 * u); c.lineTo(x, y - 30 * u); c.lineTo(x + 16 * u, y + 8 * u); c.closePath(); c.fill(); c.fillStyle = '#fff'; c.fillRect(x - 9 * u, y - 10 * u, 18 * u, 5 * u); } }\n    // ba\u015flang\u0131\u00e7 / biti\u015f\n    const sl = sx(0), fl = sx(L);\n    for (const [x, ch] of [[sl, 0], [fl, 1]]) { if (x < -40 || x > W + 40) continue; const n = 14; for (let j = 0; j < n; j++) { c.fillStyle = (j + ch) % 2 ? '#fff' : '#111'; c.fillRect(x - 5 * u, lane[0] - 40 * u + j * ((lane[1] + 30 * u - lane[0] + 40 * u) / n), 10 * u, (lane[1] + 30 * u - lane[0] + 40 * u) / n); } }\n    // ko\u015fucular\n    const sp = [at(rc.P[0], rt + .1) - pm, at(rc.P[1], rt + .1) - pe];\n    for (let i = 0; i < 2; i++) { const p = i ? pe : pm, x = clamp(sx(p), W * .08, W * .92), uu = Math.min(H * .031, W * .04);\n      const e = rc.ev.find(z => z.i === i && rt - z.t >= 0 && rt - z.t < 1.3);\n      for (let j = 0; j < 7; j++) { const a = (((rt * 2 + j * .37) % 1) + 1) % 1; c.fillStyle = 'rgba(255,255,255,' + (.35 * (1 - a)) + ')'; c.beginPath(); c.arc(x - uu * 1.6 - a * uu * 7, lane[i] - uu * .3 - (j % 3) * uu * .35, uu * (.25 + .3 * a), 0, 7); c.fill(); }\n      runner(c, i, x, lane[i], uu, tm * 1000, run ? clamp(sp[i] * .018, 0, .12) + (e && e.k === 'boost' ? .1 : 0) : 0, i * 1.7);\n      txt(c, NAME[i], x, lane[i] - uu * 7.2, 15 * u, COL[i], { glow: COL[i] });\n      if (e) txt(c, e.k === 'boost' ? '\u26a1 HIZLANDI!' : '\ud83c\udf4c TAKILDI!', x + uu * 4.2, lane[i] - uu * 4.4 - (rt - e.t) * 14 * u, 16 * u, e.k === 'boost' ? '#8ef' : '#ffb25a'); }\n    // \u00fcst bar: ilerleme\n    const bx = W * .12, bw = W * .76; c.fillStyle = 'rgba(255,255,255,.12)'; rr(c, bx, H * .035, bw, 8 * u, 4 * u); c.fill();\n    for (let i = 0; i < 2; i++) { c.fillStyle = COL[i]; c.beginPath(); c.arc(bx + bw * clamp((i ? pe : pm) / L, 0, 1), H * .035 + 4 * u + (i ? 3 : -3) * u, 8 * u, 0, 7); c.fill(); }\n    txt(c, '\ud83c\udfc1', bx + bw + 14 * u, H * .035 + 4 * u, 18 * u, '#fff');\n    txt(c, 'YARI\u015e ' + (sg.i + 1) + ' / ' + (w.max || 3), W / 2, H * .205, 20 * u, '#fff'); dots(c, W, H, u, w, sg.i);\n    // geri say\u0131m / biti\u015f\n    const sinceCd = tm - sg.cd;\n    if (tm < sg.go) { const n = Math.ceil(sg.go - tm), ph = (sg.go - tm) % 1; cue('c' + sg.i + n, () => sfx(520, .12, 'square', .2)); txt(c, String(n), W / 2, H * .55, H * (.2 + .12 * ph), '#fff', { glow: '#fff' }); }\n    else if (rt < 1.1) { cue('go' + sg.i, () => sfx(880, .35, 'square', .25)); txt(c, 'BA\u015eLA!', W / 2, H * .55, H * .16, '#ffe14a', { glow: '#fa0' }); }\n    if (tm >= sg.fin && tm < sg.end) { cue('f' + sg.i, () => { sfx(660, .15, 'triangle', .25); sfx(990, .3, 'triangle', .25); }); txt(c, 'B\u0130T\u0130\u015e!', W / 2, H * .55, H * .15, COL[rc.win], { glow: COL[rc.win] }); }\n    if (tm >= sg.end) { const f = clamp((tm - sg.end) / .4, 0, 1); c.save(); c.globalAlpha = f; c.fillStyle = 'rgba(0,0,0,.6)'; c.fillRect(0, 0, W, H); rr(c, W * .2, H * .3, W * .6, H * .4, 20 * u); c.fillStyle = COLD[rc.win]; c.fill(); c.lineWidth = 4 * u; c.strokeStyle = COL[rc.win]; c.stroke();\n      txt(c, (sg.i + 1) + '. YARI\u015eI KAZANAN', W / 2, H * .39, 24 * u, '#fff'); txt(c, NAME[rc.win], W / 2, H * .51, 64 * u, '#fff', { glow: COL[rc.win] });\n      txt(c, NAME[0] + ' ' + rc.fin[0].toFixed(2) + ' sn   \u00b7   ' + NAME[1] + ' ' + rc.fin[1].toFixed(2) + ' sn', W / 2, H * .62, 17 * u, '#dde'); c.restore();\n      cue('r' + sg.i, () => { sfx(523, .2, 'triangle', .22); sfx(784, .35, 'triangle', .22); }); }\n  }\n  function drawIntro(c, W, H, tm, w) { hit = [];\n    const u = H / 540; bg(c, W, H, null, tm);\n    c.save(); c.beginPath(); c.moveTo(0, 0); c.lineTo(W * .56, 0); c.lineTo(W * .44, H); c.lineTo(0, H); c.closePath(); c.fillStyle = 'rgba(255,50,60,.28)'; c.fill(); c.restore();\n    c.save(); c.beginPath(); c.moveTo(W, 0); c.lineTo(W * .56, 0); c.lineTo(W * .44, H); c.lineTo(W, H); c.closePath(); c.fillStyle = 'rgba(50,130,255,.28)'; c.fill(); c.restore();\n    const e = clamp(tm / 1.2, 0, 1), uu = Math.min(H * .06, W * .06);\n    runner(c, 0, W * (.12 + .26 * e), H * .86, uu, tm * 1000 * .5, 0, 0); runner(c, 1, W * (.88 - .26 * e), H * .86, uu, tm * 1000 * .5, 0, 1.7);\n    txt(c, 'MERT  \u2715  EREN', W / 2, H * .2, Math.min(70 * u, W * .09), '#fff', { glow: '#fff' });\n    txt(c, '1. HAFTA \u00b7 S\u0130M\u00dcLASYON YARI\u015eI', W / 2, H * .33, 28 * u, '#ffe14a');\n    txt(c, 'Botlar 3 kez yar\u0131\u015f\u0131r \u00b7 \u00e7o\u011funlu\u011fu kazanan 1 puan al\u0131r', W / 2, H * .43, 18 * u, '#dde');\n    cue('i', () => sfx(330, .3, 'triangle', .2));\n  }\n  function drawVote(c, W, H, tm, w) {\n    const u = H / 540, k = tm - w.vote, left = Math.max(0, VOTE - k), v = myVote(wk); bg(c, W, H, null, tm); hit = [];\n    txt(c, 'K\u0130M KAZANIR?', W / 2, H * .13, Math.min(56 * u, W * .08), '#fff', { glow: '#fff' });\n    txt(c, 'Yar\u0131\u015ftan \u00f6nce tahminini yap \u00b7 ' + Math.ceil(left) + ' sn', W / 2, H * .23, 19 * u, '#ffe14a');\n    const cw = Math.min(W * .36, 330 * u), ch = H * .5, y = H * .3;\n    for (let i = 0; i < 2; i++) {\n      const x = W / 2 + (i ? 1 : -1) * (cw / 2 + 18 * u) - cw / 2, sel = v === i, pulse = sel ? 1 + .02 * Math.sin(tm * 6) : 1;\n      c.save(); c.translate(x + cw / 2, y + ch / 2); c.scale(pulse, pulse); c.translate(-(x + cw / 2), -(y + ch / 2));\n      const g = c.createLinearGradient(x, y, x, y + ch); g.addColorStop(0, COLD[i]); g.addColorStop(1, '#0a0814'); c.fillStyle = g; rr(c, x, y, cw, ch, 22 * u); c.fill(); c.lineWidth = sel ? 6 * u : 2 * u; c.strokeStyle = sel ? '#fff' : COL[i]; if (sel) { c.shadowColor = COL[i]; c.shadowBlur = 24 * u; } c.stroke(); c.shadowBlur = 0; c.restore();\n      c.save(); c.beginPath(); rr(c, x, y, cw, ch, 22 * u); c.clip(); runner(c, i, x + cw / 2, y + ch * .78, Math.min(ch * .085, cw * .08), tm * 1000 * .4, 0, i * 1.7); c.restore();\n      txt(c, NAME[i], x + cw / 2, y + 34 * u, 34 * u, '#fff', { glow: COL[i] }); txt(c, TAG[i], x + cw / 2, y + 62 * u, 15 * u, COL[i]);\n      if (sel) txt(c, '\u2714 TAHM\u0130N\u0130N', x + cw / 2, y + ch - 24 * u, 20 * u, '#fff', { glow: COL[i] }); else txt(c, 'DOKUN \u00b7 OY VER', x + cw / 2, y + ch - 24 * u, 15 * u, 'rgba(255,255,255,.7)', { w: 800 });\n      hit.push({ x, y, w: cw, h: ch, i });\n    }\n    c.fillStyle = 'rgba(255,255,255,.12)'; rr(c, W * .2, H * .88, W * .6, 8 * u, 4 * u); c.fill(); c.fillStyle = '#ffe14a'; rr(c, W * .2, H * .88, Math.max(8 * u, W * .6 * left / VOTE), 8 * u, 4 * u); c.fill();\n    cue('v' + Math.ceil(left), () => { if (left < 4) sfx(500, .08, 'square', .12); });\n  }\n  function drawTally(c, W, H, tm, w) {\n    const u = H / 540, k = tm - w.tally; bg(c, W, H, null, tm);\n    txt(c, 'HAFTANIN SONUCU', W / 2, H * .2, 30 * u, '#fff');\n    for (let i = 0; i < 3; i++) { const x = W / 2 + (i - 1) * 150 * u, show = k > .5 + i * .7; c.fillStyle = show ? COLD[w.races[i].win] : 'rgba(255,255,255,.1)'; rr(c, x - 60 * u, H * .3, 120 * u, 90 * u, 14 * u); c.fill(); c.strokeStyle = show ? COL[w.races[i].win] : 'rgba(255,255,255,.2)'; c.lineWidth = 3 * u; c.stroke(); txt(c, (i + 1) + '. YARI\u015e', x, H * .3 + 22 * u, 14 * u, '#cdd'); txt(c, show ? NAME[w.races[i].win] : '?', x, H * .3 + 58 * u, 28 * u, show ? '#fff' : '#889'); }\n    if (k > 3) { txt(c, NAME[0] + ' ' + w.wins[0] + '  \u2013  ' + w.wins[1] + ' ' + NAME[1], W / 2, H * .62, 54 * u, '#fff', { glow: COL[w.win] }); cue('t', () => sfx(440, .4, 'sawtooth', .18)); }\n    else txt(c, 'Hesaplan\u0131yor' + '.'.repeat(1 + Math.floor(k * 3) % 3), W / 2, H * .62, 28 * u, '#aab');\n  }\n  function drawCel(c, W, H, tm, w, wi) {\n    const u = H / 540, k = tm - w.cel, wn = w.win, lo = 1 - wn; bg(c, W, H, COL[wn], tm);\n    // \u0131\u015f\u0131k huzmesi\n    c.save(); c.globalAlpha = .18 + .06 * Math.sin(k * 4); c.fillStyle = COL[wn]; c.beginPath(); c.moveTo(W * .5 - 40 * u, 0); c.lineTo(W * .5 + 40 * u, 0); c.lineTo(W * .5 + 260 * u, H); c.lineTo(W * .5 - 260 * u, H); c.closePath(); c.fill(); c.restore();\n    // konfeti (zamandan deterministik)\n    const rnd = mul(77); for (let i = 0; i < 110; i++) { const x0 = rnd() * W, sp = 60 + rnd() * 120, ph = rnd() * 9, sz = 5 + rnd() * 7, cc = rnd() < .5 ? COL[wn] : (rnd() < .5 ? '#ffe14a' : '#fff'); const y = ((k * sp + ph * 90) % (H + 40)) - 20, x = x0 + Math.sin(k * 2 + ph) * 30 * u; c.save(); c.translate(x, y); c.rotate(k * 3 + ph); c.fillStyle = cc; c.fillRect(-sz / 2, -sz / 4, sz, sz / 2); c.restore(); }\n    const pts = totals()[wn] || 1, big = Math.min(H * .075, W * .07), base = H * .84;\n    // kaybeden: k\u00fc\u00e7\u00fck, \u00fczg\u00fcn\n    c.save(); c.globalAlpha = .7; c.translate(W * (lo ? .84 : .16), base + 6 * u); c.scale(.55, .55); c.translate(-W * (lo ? .84 : .16), -(base + 6 * u)); runner(c, lo, W * (lo ? .84 : .16), base + 6 * u, big, k * 300, .16, 0); c.restore();\n    // kazanan hareketi\n    const px = W / 2; c.save();\n    if (wn === 0) { // Mert (Ad_bu41): z\u0131pla + takla\n      const ph = (k % 2.4) / 2.4, jump = Math.sin(clamp(ph / .7, 0, 1) * Math.PI) * big * 3.2, rot = ph < .7 ? clamp(ph / .7, 0, 1) * Math.PI * 2 : 0, cy = base - big * 3 - jump;\n      c.translate(px, cy); c.rotate(rot); c.translate(-px, -cy);\n      c.translate(0, -jump);\n    } else { // Eren (koftepapates): k\u00f6fte dans\u0131 \u2014 sa\u011fa sola sallan + z\u0131pla + s\u0131k\u0131\u015f-uzama\n      const sw = Math.sin(k * 9), hop = Math.abs(Math.sin(k * 4.5)) * big * .9, sq = 1 + .08 * Math.cos(k * 9);\n      c.translate(px, base); c.rotate(sw * .22); c.scale(1 / sq, sq); c.translate(-px, -base); c.translate(sw * big * .4, -hop);\n    }\n    runner(c, wn, px, base, big, k * 700, 0, 0); c.restore();\n    const head = wn === 0 ? (pts === 1 ? 'MERT \u0130LK PUANI ALDI!' : 'MERT PUAN ALDI!') : (pts === 1 ? 'EREN 1 PUAN ALDI!' : 'EREN PUAN ALDI!');\n    const pop = clamp(k / .5, 0, 1), sc = 1 + (1 - pop) * .8;\n    txt(c, head, W / 2, H * .17, Math.min(52 * u, W * .075) * sc, '#fff', { glow: COL[wn] });\n    txt(c, TAG[wn], W / 2, H * .27, 20 * u, COL[wn]);\n    cue('cel', () => { [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => sfx(f, .3, 'triangle', .22), i * 140)); });\n    if (Math.floor(k * 1.4) !== Math.floor((k - .02) * 1.4) && k < 12) sfx(300 + (Math.floor(k * 1.4) % 4) * 120, .12, 'square', .1);\n  }\n  function drawFinal(c, W, H, tm, w, wi) {\n    const u = H / 540, wn = w.win; bg(c, W, H, COL[wn], tm); const p = totals(), sum = Math.max(1, p[0] + p[1]);\n    txt(c, (wi + 1) + '. HAFTA TAMAMLANDI', W / 2, H * .18, 30 * u, '#ffe14a');\n    txt(c, 'HAFTANIN GAL\u0130B\u0130: ' + NAME[wn], W / 2, H * .3, 40 * u, COL[wn], { glow: COL[wn] });\n    txt(c, NAME[0] + '  ' + p[0] + '  \u2013  ' + p[1] + '  ' + NAME[1], W / 2, H * .46, Math.min(70 * u, W * .1), '#fff', { glow: '#fff' });\n    const bx = W * .15, bw = W * .7, by = H * .58, bh = 34 * u; c.fillStyle = 'rgba(255,255,255,.1)'; rr(c, bx, by, bw, bh, 17 * u); c.fill();\n    c.save(); rr(c, bx, by, bw, bh, 17 * u); c.clip(); c.fillStyle = COL[0]; c.fillRect(bx, by, bw * p[0] / sum, bh); c.fillStyle = COL[1]; c.fillRect(bx + bw * p[0] / sum, by, bw * p[1] / sum, bh); c.restore();\n    txt(c, Math.round(100 * p[0] / sum) + '%', bx + 36 * u, by + bh / 2, 17 * u, '#fff'); txt(c, Math.round(100 * p[1] / sum) + '%', bx + bw - 36 * u, by + bh / 2, 17 * u, '#fff');\n    const v = myVote(wi); if (v >= 0) txt(c, v === wn ? '\u2714 Tahminin do\u011fruydu! (' + NAME[v] + ')' : '\u2718 Tahminin tutmad\u0131 (' + NAME[v] + ')', W / 2, H * .72, 21 * u, v === wn ? '#7dffa0' : '#ff9a9a');\n    txt(c, 'Sonraki hafta yak\u0131nda...', W / 2, H * .8, 18 * u, '#cde');\n    if (!lget('vd_mxr_seen' + wi)) lput('vd_mxr_seen' + wi, '1');\n  }\n  function frame() {\n    raf = requestAnimationFrame(frame); if (!cv) return;\n    const r = ov.getBoundingClientRect(), W = Math.max(2, r.width | 0), H = Math.max(2, r.height | 0);\n    if (cv.width !== W * dpr || cv.height !== H * dpr) { cv.width = W * dpr; cv.height = H * dpr; }\n    cx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    const w = W1[wk];\n    if (mode === 'info') { drawInfo(cx, W, H); return; }\n    const tm = (Date.now() - t0) / 1000;\n    if (tm < INTRO) drawIntro(cx, W, H, tm, w);\n    else if (tm < INTRO + VOTE) drawVote(cx, W, H, tm, w);\n    else if (tm >= w.total) drawFinal(cx, W, H, tm, w, wk);\n    else if (tm >= w.cel) drawCel(cx, W, H, tm, w, wk);\n    else if (tm >= w.tally) drawTally(cx, W, H, tm, w);\n    else { const sg = w.seg.find(s => tm < s.res) || w.seg[2]; drawRace(cx, W, H, tm, w, sg); }\n    $('mxrAgain').style.display = tm >= w.total ? '' : 'none';\n  }\n  const fmt = ms => { const s = Math.max(0, Math.floor(ms / 1000)), d = Math.floor(s / 86400); return (d ? d + 'g ' : '') + String(Math.floor(s / 3600) % 24).padStart(2, '0') + ':' + String(Math.floor(s / 60) % 60).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };\n  function drawInfo(c, W, H) {\n    const u = H / 540; bg(c, W, H, null, 0); const left = START - Date.now();\n    txt(c, 'MERT  \u2715  EREN', W / 2, H * .16, Math.min(66 * u, W * .09), '#fff', { glow: '#fff' });\n    txt(c, '1. HAFTA \u00b7 S\u0130M\u00dcLASYON YARI\u015eI', W / 2, H * .28, 26 * u, '#ffe14a');\n    ['Mert ve Eren botlar\u0131 pistte 3 kez yar\u0131\u015f\u0131r.', 'Herkes ayn\u0131 anda, ayn\u0131 yar\u0131\u015f\u0131 izler.', '3 yar\u0131\u015f bitince \u00e7o\u011funlu\u011fu kazanan 1 puan al\u0131r;', 'kazanan\u0131n avatar\u0131 sevin\u00e7 hareketi yapar.', 'Etkinlik 18 Kas\u0131m \u2013 11 Ocak, her hafta yeni bir b\u00f6l\u00fcm.'].forEach((s, i) => txt(c, s, W / 2, H * (.4 + i * .07), 18 * u, '#dde', { w: 700 }));\n    txt(c, left > 0 ? 'YARI\u015e BA\u015eLAMASINA  ' + fmt(left) : 'YARI\u015e BA\u015eLADI!', W / 2, H * .82, 30 * u, '#fff', { glow: '#f55' });\n    txt(c, '18 Kas\u0131m \u00b7 15:00', W / 2, H * .9, 18 * u, '#ffe14a');\n  }\n  function open(m, tt) {\n    if (!ov) build_dom(); mode = m; wk = 0; t0 = tt; lastCue = ''; ov.style.display = 'flex'; document.body.classList.add('mxr-on'); cancelAnimationFrame(raf); raf = requestAnimationFrame(frame);\n    $('mxrAgain').style.display = 'none';\n  }\n  function close() { if (!ov) return; ov.style.display = 'none'; document.body.classList.remove('mxr-on'); cancelAnimationFrame(raf); if (mode === 'live') sput('vd_mxr_closed', '1'); mode = null; }\n  function build_dom() {\n    ov = document.createElement('div'); ov.id = 'mxr'; ov.innerHTML = '<canvas></canvas><button type=\"button\" id=\"mxrX\">\u2715</button><button type=\"button\" id=\"mxrAgain\">\u21bb TEKRAR \u0130ZLE</button>'; document.body.appendChild(ov);\n    cv = ov.querySelector('canvas'); cx = cv.getContext('2d'); dpr = Math.min(2, window.devicePixelRatio || 1);\n    cv.addEventListener('pointerdown', e => { const r = cv.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top; for (const h of hit) if (x >= h.x && x <= h.x + h.w && y >= h.y && y <= h.y + h.h && (Date.now() - t0) / 1000 < INTRO + VOTE) { M.vote(h.i); sfx(700, .1, 'triangle', .2); } });\n    $('mxrX').onclick = close; $('mxrAgain').onclick = () => open('replay', Date.now()); addEventListener('keydown', e => { if (e.key === 'Escape' && mode) close(); });\n  }\n  M.open = () => { const now = Date.now(); if (now < START) open('info', 0); else open(now < START + W1[0].total * 1000 ? 'live' : 'replay', now < START + W1[0].total * 1000 ? START : now); };\n  M.h = { txt, rr, runner, bg, COL, COLD, NAME, TAG, fmt, lget, lput, mul, mix, font, sim, clamp, at };\n  M.drawRace = drawRace; M.result = () => ({ win: W1[0].win, wins: W1[0].wins, ready: Date.now() >= START + W1[0].total * 1000 });\n  M.demoSeed = sd => { WEEKS[0].seed = sd; W1[0] = build(WEEKS[0]); };\n  M.sim = sim; M.build = build; M.START = START;\n\n  /* ---------- men\u00fc d\u00fc\u011fmesi + otomatik a\u00e7\u0131l\u0131\u015f ---------- */\n  function menuOk() { const m = $('menu'), h = $('hud'); return m && !m.classList.contains('hidden') && !(h && !h.classList.contains('hidden')) && !document.querySelector('.modal:not(.hidden)') && !mode; }\n  function tick() {\n    const b = $('mxrBtn'); if (!b) return; const now = Date.now(), w = W1[0], endLive = START + w.total * 1000, mxOn = VD.Mx && VD.Mx.on();\n    const show = menuOk() && now < END && (now >= START || mxOn); b.classList.toggle('hidden', !show);\n    const live = now >= START && now < endLive; b.classList.toggle('live', live);\n    const p = totals(); b.querySelector('b').textContent = now < START ? '\ud83c\udfc1 1. HAFTA' : live ? '\ud83d\udd34 CANLI YARI\u015e' : '\ud83c\udfc1 MERT ' + p[0] + ' \u2013 ' + p[1] + ' EREN';\n    b.querySelector('small').textContent = now < START ? '18 KASIM 15:00 \u00b7 ' + fmt(START - now) : live ? '\u0130ZLE' : 'TEKRAR \u0130ZLE';\n    if (live && menuOk() && !sget('vd_mxr_closed')) M.open();\n  }\n  function init() {\n    const b = document.createElement('button'); b.id = 'mxrBtn'; b.type = 'button'; b.className = 'hidden'; b.innerHTML = '<b></b><small></small>'; document.body.appendChild(b);\n    b.onclick = ev => { ev.stopPropagation(); M.open(); }; b.addEventListener('pointerdown', ev => ev.stopPropagation());\n    tick(); setInterval(tick, 800);\n  }\n  if (document.body && $('menu')) init(); else document.addEventListener('DOMContentLoaded', init);\n})();\n</script>\n<script>/* MERT \u00d7 EREN \u2014 2. HAFTA: TAKIM SAVA\u015eI.\n   25 Kas\u0131m 15:00 \u2192 2 Aral\u0131k 15:00 (TR). Herkes Mert veya Eren tak\u0131m\u0131na girer; ma\u00e7 kazanmak +3, ma\u00e7\u0131 bitirmek +1 puan.\n   Sunucu varsa herkesin puan\u0131 /team \u00fczerinde toplan\u0131r (canl\u0131 y\u00fczde \u00e7ubu\u011fu); sunucu yoksa yaln\u0131zca bu cihaz\u0131n puan\u0131 g\u00f6r\u00fcn\u00fcr.\n   Hafta bitince kazanan tak\u0131m\u0131n rengi men\u00fcye 1 hafta boyunca gelir. */\n(function () {\n  'use strict';\n  const VD = window.VD = window.VD || {}, T = VD.Team = {};\n  const $ = id => document.getElementById(id);\n  const demo = /[?&]mxt=demo/.test(location.search), n0 = Date.now();\n  const AT = demo ? n0 - 3.5 * 864e5 : Date.UTC(2026, 10, 25, 12, 0, 0), END = demo ? n0 + 3.5 * 864e5 : Date.UTC(2026, 11, 2, 12, 0, 0);\n  const SHOW0 = AT - 3 * 864e5, SHOW1 = END + 7 * 864e5;\n  const H = () => VD.Mxr && VD.Mxr.h;\n  const lget = k => { try { return localStorage.getItem(k); } catch (e) { return null; } }, lput = (k, v) => { try { localStorage.setItem(k, v); } catch (e) {} };\n  const cid = () => { let c = lget('vd_mxt_cid'); if (!c) { c = 'p' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36); lput('vd_mxt_cid', c); } return c; };\n  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));\n  let D = { s: [0, 0], n: [0, 0], my: -1, pts: 0, fin: false, ok: false }, disp = [0, 0], hit = [], pop = null, cap = '';\n  try { const j = JSON.parse(lget('vd_mxt_d') || 'null'); if (j && j.s) D = Object.assign(D, j, { ok: false, cached: true }); } catch (e) {}\n  T.cap = s => { cap = s || ''; };\n  const side = () => D.my >= 0 ? D.my : (lget('vd_mxt_side') === '1' ? 1 : lget('vd_mxt_side') === '0' ? 0 : -1);\n  const base = () => { const h = VD.Host; return h && h.A && h.A.srvOk && h.httpBase ? h.httpBase() : ''; };\n  const phase = () => { const n = Date.now(); return n < AT ? 'pre' : n < END ? 'live' : 'fin'; };\n  async function api(body) {\n    const b = base();\n    if (!b) { // sunucusuz: yaln\u0131zca bu cihaz\n      const L = (() => { try { return JSON.parse(lget('vd_mxt_loc') || '{}'); } catch (e) { return {}; } })(); L.p = L.p || 0; L.s = L.s || [0, 0];\n      if (body && body.pts && phase() === 'live' && side() >= 0) { L.p += body.pts; L.s[side()] += body.pts; lput('vd_mxt_loc', JSON.stringify(L)); }\n      D = Object.assign(D, { s: L.s, pts: L.p, my: side(), ok: false, fin: phase() === 'fin' }); return;\n    }\n    try {\n      const r = await fetch(b + '/team' + (body ? '' : '?wk=w2&cid=' + cid()), body ? { method: 'POST', headers: { 'content-type': 'text/plain' }, body: JSON.stringify(Object.assign({ wk: 'w2', cid: cid() }, body)) } : undefined);\n      const j = await r.json(); if (j && j.s) { D = Object.assign({}, j, { ok: true, cached: false }); lput('vd_mxt_d', JSON.stringify({ s: j.s, n: j.n, fin: j.fin })); if (j.my >= 0) lput('vd_mxt_side', String(j.my)); }\n    } catch (e) {}\n  }\n  T.refresh = () => api(null);\n  T.pick = k => { if (side() >= 0 && phase() !== 'pre') return; lput('vd_mxt_side', String(k)); D.my = k; api({ side: k }); };\n  T.matchDone = win => {\n    if (phase() !== 'live') return; const toast = VD.Host && VD.Host.toast, nm = H() ? H().NAME : ['MERT', 'EREN'];\n    if (side() < 0) { if (!T._hint) { T._hint = 1; toast && toast('\u2694\ufe0f Tak\u0131m Sava\u015f\u0131 s\u00fcr\u00fcyor! Men\u00fcden tak\u0131m\u0131n\u0131 se\u00e7, puan kazan.', 4200); } return; }\n    const p = win ? 3 : 1; pop = { t0: Date.now(), p, side: side() }; api({ pts: p }); toast && toast('\u2694\ufe0f +' + p + ' puan \u00b7 ' + nm[side()] + ' tak\u0131m\u0131', 3200);\n  };\n  T.demoPop = (p, s) => { pop = { t0: Date.now(), p, side: s }; };\n\n  /* ---------- \u00e7izim ---------- */\n  let ov = null, cv = null, cx = null, raf = 0, open = false, dpr = 1;\n  const conf = (c, W, H2, k, col) => { const r = H().mul(77); for (let i = 0; i < 100; i++) { const x0 = r() * W, sp = 50 + r() * 110, ph = r() * 9, sz = 5 + r() * 7, cc = r() < .5 ? col : (r() < .5 ? '#ffe14a' : '#fff'), y = ((k * sp + ph * 90) % (H2 + 40)) - 20; c.save(); c.translate(x0 + Math.sin(k * 2 + ph) * 28, y); c.rotate(k * 3 + ph); c.fillStyle = cc; c.fillRect(-sz / 2, -sz / 4, sz, sz / 2); c.restore(); } };\n  function draw(c, W, Hh) {\n    const h = H(); if (!h) return; const u = Hh / 540, ph = phase(), now = Date.now(), sd = side(), t = now / 1000; hit = [];\n    const tot = D.s[0] + D.s[1], tg = tot ? D.s[0] / tot : .5; disp[0] += (tg - disp[0] || 0) * .08; if (!isFinite(disp[0]) || disp[1] === 0) { disp[0] = tg; disp[1] = 1; }\n    const win = D.s[0] === D.s[1] ? -1 : D.s[0] > D.s[1] ? 0 : 1;\n    h.bg(c, W, Hh, ph === 'fin' && win >= 0 ? h.COL[win] : null, t);\n    if (ph === 'fin' && win >= 0) conf(c, W, Hh, t % 100, h.COL[win]);\n    if (ph === 'live' && sd < 0) { // tak\u0131m se\u00e7imi\n      h.txt(c, 'TARAFINI SE\u00c7', W / 2, Hh * .12, Math.min(54 * u, W * .08), '#fff', { glow: '#fff' });\n      h.txt(c, 'Bir kez se\u00e7ersin, hafta boyunca o tak\u0131mdas\u0131n', W / 2, Hh * .22, 18 * u, '#ffe14a');\n      const cw = Math.min(W * .36, 330 * u), ch = Hh * .52, y = Hh * .3;\n      for (let i = 0; i < 2; i++) { const x = W / 2 + (i ? 1 : -1) * (cw / 2 + 18 * u) - cw / 2, g = c.createLinearGradient(x, y, x, y + ch); g.addColorStop(0, h.COLD[i]); g.addColorStop(1, '#0a0814'); c.fillStyle = g; h.rr(c, x, y, cw, ch, 22 * u); c.fill(); c.lineWidth = 3 * u; c.strokeStyle = h.COL[i]; c.stroke();\n        c.save(); c.beginPath(); h.rr(c, x, y, cw, ch, 22 * u); c.clip(); h.runner(c, i, x + cw / 2, y + ch * .76, Math.min(ch * .085, cw * .08), t * 400, 0, i * 1.7); c.restore();\n        h.txt(c, 'TAKIM ' + h.NAME[i], x + cw / 2, y + 34 * u, 30 * u, '#fff', { glow: h.COL[i] }); h.txt(c, h.TAG[i], x + cw / 2, y + 62 * u, 15 * u, h.COL[i]); h.txt(c, 'DOKUN \u00b7 KATIL', x + cw / 2, y + ch - 24 * u, 16 * u, 'rgba(255,255,255,.75)'); hit.push({ x, y, w: cw, h: ch, i }); }\n    } else {\n      h.txt(c, '\u2694\ufe0f TAKIM SAVA\u015eI \u00b7 2. HAFTA', W / 2, Hh * .08, Math.min(40 * u, W * .06), '#fff', { glow: '#fff' });\n      const left = ph === 'pre' ? AT - now : END - now, s = Math.max(0, Math.floor(left / 1000)), d = Math.floor(s / 86400), f2 = n => String(n).padStart(2, '0');\n      h.txt(c, (ph === 'pre' ? 'BA\u015eLAMASINA  ' : ph === 'live' ? 'B\u0130T\u0130\u015eE  ' : 'ETK\u0130NL\u0130K B\u0130TT\u0130  ') + (ph === 'fin' ? '' : (d ? d + 'g ' : '') + f2(Math.floor(s / 3600) % 24) + ':' + f2(Math.floor(s / 60) % 60) + ':' + f2(s % 60)), W / 2, Hh * .16, 20 * u, '#ffe14a');\n      // karakterler + puanlar\n      const uu = Math.min(Hh * .05, W * .05);\n      for (let i = 0; i < 2; i++) { const cxp = W * (i ? .84 : .16), lead = (i ? 1 - disp[0] : disp[0]) > .5;\n        h.runner(c, i, cxp, Hh * .6 - (lead ? Math.abs(Math.sin(t * 5 + i)) * uu * .5 : 0), uu, t * 500, 0, i * 1.7);\n        h.txt(c, h.NAME[i], cxp, Hh * .27, 30 * u, h.COL[i], { glow: h.COL[i] }); h.txt(c, String(D.s[i]), cxp, Hh * .67, 44 * u, '#fff', { glow: h.COL[i] }); h.txt(c, 'puan', cxp, Hh * .73, 14 * u, '#cde');\n        if (D.n && D.n[i]) h.txt(c, D.n[i] + ' oyuncu', cxp, Hh * .78, 14 * u, '#9ab');\n        if (sd === i) { h.txt(c, '\u2605 SEN\u0130N TAKIMIN', cxp, Hh * .21, 14 * u, '#ffe14a'); } }\n      // orta \u00e7ubuk\n      const bx = W * .3, bw = W * .4, by = Hh * .4, bh = 44 * u; c.fillStyle = 'rgba(255,255,255,.1)'; h.rr(c, bx, by, bw, bh, 22 * u); c.fill();\n      c.save(); h.rr(c, bx, by, bw, bh, 22 * u); c.clip(); c.fillStyle = h.COL[0]; c.fillRect(bx, by, bw * disp[0], bh); c.fillStyle = h.COL[1]; c.fillRect(bx + bw * disp[0], by, bw * (1 - disp[0]), bh); c.fillStyle = '#fff'; c.fillRect(bx + bw * disp[0] - 2 * u, by, 4 * u, bh); c.restore();\n      h.txt(c, Math.round(disp[0] * 100) + '%', bx + 38 * u, by + bh / 2, 20 * u, '#fff'); h.txt(c, Math.round((1 - disp[0]) * 100) + '%', bx + bw - 38 * u, by + bh / 2, 20 * u, '#fff');\n      h.txt(c, tot ? 'CANLI SKOR' : '\u0130lk puan\u0131 sen getir!', W / 2, by - 18 * u, 15 * u, '#cde');\n      if (ph === 'fin' && win >= 0) { h.txt(c, 'KAZANAN TAKIM: ' + h.NAME[win], W / 2, Hh * .58, Math.min(34 * u, W * .05), h.COL[win], { glow: h.COL[win] }); h.txt(c, 'Bir hafta boyunca men\u00fc ' + h.NAME[win] + ' renginde!', W / 2, Hh * .66, 18 * u, '#fff'); }\n      else if (ph === 'live') { ['Ma\u00e7\u0131 kazan  +3 puan', 'Ma\u00e7\u0131 bitir  +1 puan'].forEach((s2, i) => h.txt(c, s2, W / 2, Hh * (.58 + i * .07), 19 * u, '#eef')); }\n      else h.txt(c, 'Ba\u015flay\u0131nca tak\u0131m\u0131n\u0131 se\u00e7 ve ma\u00e7 oyna!', W / 2, Hh * .6, 19 * u, '#eef');\n      if (sd >= 0 || D.pts) h.txt(c, 'Senin katk\u0131n: ' + (D.pts || 0) + ' puan', W / 2, Hh * .84, 20 * u, '#fff');\n      if (!D.ok && base() === '') h.txt(c, '\u26a0 Sunucusuz mod: yaln\u0131zca bu cihazdaki puanlar\u0131n say\u0131l\u0131r', W / 2, Hh * .93, 13 * u, '#ffb25a', { w: 700 });\n    }\n    if (pop) { const k = (Date.now() - pop.t0) / 1000; if (k > 3) pop = null; else { c.save(); c.globalAlpha = clamp(3 - k, 0, 1); h.txt(c, '+' + pop.p + ' PUAN', W / 2, Hh * (.74 - k * .03), Math.min(56 * u, W * .08) * (1 + Math.max(0, .5 - k)), h.COL[pop.side], { glow: h.COL[pop.side] }); c.restore(); } }\n    if (cap) { c.save(); c.fillStyle = 'rgba(0,0,0,.6)'; c.fillRect(0, Hh - 44 * u, W, 44 * u); c.restore(); h.txt(c, cap, W / 2, Hh - 22 * u, 17 * u, '#fff', { w: 700 }); }\n  }\n  function frame() {\n    raf = requestAnimationFrame(frame); if (!cv) return; const r = ov.getBoundingClientRect(), W = Math.max(2, r.width | 0), Hh = Math.max(2, r.height | 0);\n    if (cv.width !== W * dpr || cv.height !== Hh * dpr) { cv.width = W * dpr; cv.height = Hh * dpr; } cx.setTransform(dpr, 0, 0, dpr, 0, 0); draw(cx, W, Hh);\n  }\n  function mk() {\n    ov = document.createElement('div'); ov.id = 'mxt'; ov.className = 'mxo'; ov.innerHTML = '<canvas></canvas><button type=\"button\" id=\"mxtX\" class=\"mxX\">\u2715</button>'; document.body.appendChild(ov);\n    cv = ov.querySelector('canvas'); cx = cv.getContext('2d'); dpr = Math.min(2, window.devicePixelRatio || 1);\n    $('mxtX').onclick = T.close; addEventListener('keydown', e => { if (e.key === 'Escape' && open) T.close(); });\n    cv.addEventListener('pointerdown', e => { const r = cv.getBoundingClientRect(), x = e.clientX - r.left, y = e.clientY - r.top; for (const q of hit) if (x >= q.x && x <= q.x + q.w && y >= q.y && y <= q.y + q.h) T.pick(q.i); });\n  }\n  T.open = () => { if (!ov) mk(); open = true; ov.style.display = 'flex'; document.body.classList.add('mxr-on'); disp = [0, 0]; api(null); cancelAnimationFrame(raf); raf = requestAnimationFrame(frame); };\n  T.close = () => { if (!ov) return; open = false; ov.style.display = 'none'; document.body.classList.remove('mxr-on'); cancelAnimationFrame(raf); };\n  T.result = () => { const w = D.s[0] === D.s[1] ? -1 : D.s[0] > D.s[1] ? 0 : 1; return { win: Date.now() >= END ? w : -1, s: D.s, ok: !!D.ok || (D.cached && D.fin === true), fin: Date.now() >= END, side: side() }; };\n  T.endAt = END;\n  T.state = () => ({ D, phase: phase(), side: side() });\n\n  /* ---------- men\u00fc d\u00fc\u011fmesi + kazanan temas\u0131 ---------- */\n  const fmtl = ms => { const s = Math.max(0, Math.floor(ms / 1000)), d = Math.floor(s / 86400); return (d ? d + 'g ' : '') + String(Math.floor(s / 3600) % 24).padStart(2, '0') + ':' + String(Math.floor(s / 60) % 60).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };\n  function menuOk() { const m = $('menu'), hd = $('hud'); return m && !m.classList.contains('hidden') && !(hd && !hd.classList.contains('hidden')) && !document.querySelector('.modal:not(.hidden)') && !open && !document.body.classList.contains('mxr-on'); }\n  let lastPoll = 0;\n  function tick() {\n    const b = $('mxtBtn'); if (!b) return; const now = Date.now(), ph = phase(), nm = H() ? H().NAME : ['MERT', 'EREN'], tot = D.s[0] + D.s[1], win = D.s[0] === D.s[1] ? -1 : D.s[0] > D.s[1] ? 0 : 1;\n    const show = menuOk() && now > SHOW0 && now < SHOW1 && ((VD.Mx && VD.Mx.on && VD.Mx.on()) || now >= AT - 864e5); b.classList.toggle('hidden', !show); b.classList.toggle('live', ph === 'live');\n    if (ph === 'pre') { b.querySelector('b').textContent = '\u2694\ufe0f 2. HAFTA \u00b7 TAKIM SAVA\u015eI'; b.querySelector('small').textContent = '25 KASIM 15:00 \u00b7 ' + fmtl(AT - now); }\n    else if (ph === 'live') { b.querySelector('b').textContent = tot ? '\u2694\ufe0f ' + nm[0] + ' %' + Math.round(100 * D.s[0] / tot) + ' \u2013 %' + Math.round(100 * D.s[1] / tot) + ' ' + nm[1] : '\u2694\ufe0f TAKIM SAVA\u015eI'; b.querySelector('small').textContent = side() < 0 ? 'TAKIMINI SE\u00c7' : 'TAKIMIN: ' + nm[side()] + ' \u00b7 B\u0130T\u0130\u015eE ' + fmtl(END - now); }\n    else { b.querySelector('b').textContent = win >= 0 ? '\ud83c\udfc6 KAZANAN: ' + nm[win] : '\u2694\ufe0f TAKIM SAVA\u015eI B\u0130TT\u0130'; b.querySelector('small').textContent = 'SONU\u00c7'; }\n    document.body.classList.toggle('tw0', ph === 'fin' && win === 0 && now < SHOW1); document.body.classList.toggle('tw1', ph === 'fin' && win === 1 && now < SHOW1);\n    if (show && now - lastPoll > 20000 && now > SHOW0) { lastPoll = now; if (ph !== 'pre') api(null); }\n  }\n  function init() {\n    const b = document.createElement('button'); b.id = 'mxtBtn'; b.type = 'button'; b.className = 'hidden'; b.innerHTML = '<b></b><small></small>'; document.body.appendChild(b);\n    b.onclick = ev => { ev.stopPropagation(); T.open(); }; b.addEventListener('pointerdown', ev => ev.stopPropagation()); tick(); setInterval(tick, 900);\n  }\n  if (document.body && $('menu')) init(); else document.addEventListener('DOMContentLoaded', init);\n})();\n</script>\n<script>/* MERT \u00d7 EREN \u2014 PART 3: B\u00dcY\u00dcK F\u0130NAL + \u015eAMP\u0130YONLUK T\u00d6REN\u0130 (11 Ocak 15:00 TR).\n   Puan: 1. hafta yar\u0131\u015f\u0131n\u0131n galibi +1, 2. hafta tak\u0131m sava\u015f\u0131n\u0131n galibi +1. Bir tak\u0131m 2 puana ula\u015ft\u0131ysa \u015fampiyon belli olur\n   (t\u00f6ren yap\u0131l\u0131r); de\u011filse \"B\u00fcy\u00fck Final\" (5 yar\u0131\u015fl\u0131k seri, ilk 3'\u00fc alan) \u015fampiyonu belirler.\n   \u00d6d\u00fcl (kazanan tak\u0131m\u0131n oyuncular\u0131na): \u015eampiyon Tac\u0131 (tak\u0131m rengi), Alt\u0131n Neon, \u015fampiyon rozeti. Se\u00e7ti\u011fin tak\u0131m ekranda hep g\u00f6r\u00fcn\u00fcr. */\n(function () {\n  'use strict';\n  const VD = window.VD = window.VD || {}, F = VD.Final = {};\n  const $ = id => document.getElementById(id);\n  const demo = /[?&]mxf=demo/.test(location.search), n0 = Date.now();\n  const FSTART = demo ? n0 + 4000 : Date.UTC(2027, 0, 11, 12, 0, 0), SHOW0 = FSTART - 3 * 864e5, SHOW1 = FSTART + 14 * 864e5;\n  const H = () => VD.Mxr && VD.Mxr.h;\n  const sget = k => { try { return sessionStorage.getItem(k); } catch (e) { return null; } }, sput = (k, v) => { try { sessionStorage.setItem(k, v); } catch (e) {} };\n  let over = null; // deneme/video: {p1,p2,side,seed}\n  F.demo = o => { over = o; plan = null; };\n  const FSEED = 9100;\n  const INTRO = 8, RECAP = 11, CD = 3, TAIL = 2, RES = 3.5, REV = 9, CEL = 18, PRZ = 12;\n  let plan = null;\n  function results() {\n    const r1 = VD.Mxr ? VD.Mxr.result() : { win: -1 }, r2 = VD.Team ? VD.Team.result() : { win: -1, ok: false, side: -1 };\n    if (over) return { p1: over.p1, p2: over.p2, side: over.side, ok: true };\n    return { p1: r1.win, p2: r2.ok ? r2.win : -1, side: r2.side, ok: r2.ok };\n  }\n  function mkPlan(p1, p2, seed) {\n    const h = H(), pts = [0, 0]; if (p1 >= 0) pts[p1]++; if (p2 >= 0) pts[p2]++;\n    const pre = pts.slice(), decided = pts[0] >= 2 || pts[1] >= 2, races = [], wins = [0, 0], seg = [];\n    let t = INTRO + RECAP;\n    if (!decided) for (let n = 1; n <= 5 && wins[0] < 3 && wins[1] < 3; n++) { const rc = h.sim((seed || FSEED) * 10 + n); races.push(rc); wins[rc.win]++; seg.push({ i: n - 1, cd: t, go: t + CD, fin: t + CD + rc.dur, end: t + CD + rc.dur + TAIL, res: t + CD + rc.dur + TAIL + RES }); t += CD + rc.dur + TAIL + RES; }\n    const finalWin = decided ? -1 : (wins[0] > wins[1] ? 0 : 1); if (!decided) pts[finalWin]++;\n    const champ = decided ? (pts[0] > pts[1] ? 0 : 1) : finalWin;\n    const P = { p1, p2, pts, pre, decided, races, wins, seg, max: 5, finalWin, champ, reveal: t, cel: t + REV, prize: t + REV + CEL, card: t + REV + CEL + PRZ };\n    const cnt = w => (i, tm) => { let a = 0; seg.forEach((s, j) => { if ((j < i || (j === i && tm >= s.end)) && races[j].win === w) a++; }); return a; };\n    P.wins0 = cnt(0); P.wins1 = cnt(1); return P;\n  }\n  function getPlan() { const r = results(); if (!plan || plan.p1 !== r.p1 || plan.p2 !== r.p2) plan = mkPlan(r.p1, r.p2, over && over.seed); return plan; }\n  F.plan = getPlan;\n\n  /* ---------- sembol \u00e7izimleri ---------- */\n  const gold = (c, x0, x1) => { const g = c.createLinearGradient(x0, 0, x1, 0); g.addColorStop(0, '#a8700f'); g.addColorStop(.3, '#ffe27a'); g.addColorStop(.6, '#ffc83a'); g.addColorStop(1, '#8f5c0a'); return g; };\n  function star(c, x, y, r, col) { c.beginPath(); for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? r * .42 : r; c.lineTo(x + Math.cos(a) * rr, y + Math.sin(a) * rr); } c.closePath(); c.fillStyle = col; c.fill(); }\n  function trophy(c, x, y, s, tc) { // (x,y)=taban\u0131n alt\u0131 ortas\u0131\n    c.save(); c.translate(x, y); const h = H(), g = gold(c, -s, s); c.fillStyle = g;\n    h.rr(c, -.66 * s, -.26 * s, 1.32 * s, .26 * s, .06 * s); c.fill(); h.rr(c, -.44 * s, -.5 * s, .88 * s, .26 * s, .05 * s); c.fill(); c.fillRect(-.12 * s, -1.02 * s, .24 * s, .54 * s);\n    c.lineWidth = .15 * s; c.strokeStyle = g; c.beginPath(); c.arc(-.74 * s, -1.68 * s, .3 * s, Math.PI * .45, Math.PI * 1.55); c.stroke(); c.beginPath(); c.arc(.74 * s, -1.68 * s, .3 * s, -Math.PI * .55, Math.PI * .55); c.stroke();\n    c.beginPath(); c.moveTo(-.72 * s, -2.1 * s); c.lineTo(.72 * s, -2.1 * s); c.bezierCurveTo(.72 * s, -1.3 * s, .4 * s, -1.04 * s, 0, -1.02 * s); c.bezierCurveTo(-.4 * s, -1.04 * s, -.72 * s, -1.3 * s, -.72 * s, -2.1 * s); c.closePath(); c.fillStyle = g; c.fill();\n    c.save(); c.globalAlpha = .35; c.fillStyle = '#fff'; c.beginPath(); c.moveTo(-.5 * s, -2.0 * s); c.lineTo(-.3 * s, -2.0 * s); c.lineTo(-.18 * s, -1.2 * s); c.lineTo(-.34 * s, -1.2 * s); c.fill(); c.restore();\n    star(c, 0, -1.6 * s, .3 * s, tc || '#fff'); c.restore();\n  }\n  function crown(c, x, y, w, tc) { // (x,y)=alt orta\n    c.save(); c.translate(x, y); const g = gold(c, -w / 2, w / 2), hh = w * .55; c.fillStyle = g; c.beginPath(); c.moveTo(-w / 2, 0); c.lineTo(-w / 2, -hh * .55); c.lineTo(-w * .25, -hh * .25); c.lineTo(-w * .12, -hh); c.lineTo(0, -hh * .35); c.lineTo(w * .12, -hh); c.lineTo(w * .25, -hh * .25); c.lineTo(w / 2, -hh * .55); c.lineTo(w / 2, 0); c.closePath(); c.fill();\n    c.fillStyle = tc; for (const gx of [-.38, 0, .38]) { c.beginPath(); c.arc(gx * w, -hh * .12, w * .045, 0, 7); c.fill(); } c.fillStyle = '#fff'; for (const gx of [-.12, .12]) { c.beginPath(); c.arc(gx * w, -hh * 1.02, w * .03, 0, 7); c.fill(); } c.restore();\n  }\n  function rays(c, W, Hh, t, col, a) { c.save(); c.translate(W / 2, Hh * .55); c.rotate(t * .12); c.globalAlpha = a; c.fillStyle = col; const R = Math.max(W, Hh); for (let i = 0; i < 14; i++) { c.rotate(Math.PI * 2 / 14); c.beginPath(); c.moveTo(0, 0); c.lineTo(R, -R * .06); c.lineTo(R, R * .06); c.closePath(); c.fill(); } c.restore(); }\n  function fireworks(c, W, Hh, t, cols) {\n    const h = H(), u = Hh / 540;\n    for (let b = 0; b < 5; b++) { const k = t - b * .5, T = 2.4, n = Math.floor(k / T), lt = k - n * T; if (k < 0 || lt > 1.9) continue; const r = h.mul(n * 31 + b * 7 + 5), x = W * (.1 + .8 * r()), y = Hh * (.1 + .28 * r()), col = cols[(n + b) % cols.length];\n      for (let i = 0; i < 28; i++) { const a = i / 28 * 6.283 + r() * .2, v = (70 + r() * 90) * u, d = v * lt * (1 - lt * .22), px = x + Math.cos(a) * d, py = y + Math.sin(a) * d + 45 * u * lt * lt; c.save(); c.globalAlpha = Math.max(0, 1 - lt / 1.9); c.fillStyle = col; c.beginPath(); c.arc(px, py, 2.6 * u, 0, 7); c.fill(); c.restore(); } }\n  }\n  function confetti(c, W, Hh, k, col) { const r = H().mul(91); for (let i = 0; i < 120; i++) { const x0 = r() * W, sp = 50 + r() * 110, ph = r() * 9, sz = 5 + r() * 7, cc = r() < .45 ? col : (r() < .5 ? '#ffe14a' : '#fff'), y = ((k * sp + ph * 90) % (Hh + 40)) - 20; c.save(); c.translate(x0 + Math.sin(k * 2 + ph) * 28, y); c.rotate(k * 3 + ph); c.fillStyle = cc; c.fillRect(-sz / 2, -sz / 4, sz, sz / 2); c.restore(); } }\n  function chip(c, W, Hh, u, side, champ, y) { // se\u00e7ilen tak\u0131m\n    const h = H(); if (side < 0) { h.txt(c, 'Tak\u0131m se\u00e7medin \u2014 izledi\u011fin i\u00e7in te\u015fekk\u00fcrler', W / 2, y, 15 * u, '#9ab'); return; }\n    const w = 380 * u, hh = 40 * u, x = W / 2 - w / 2; c.save(); c.fillStyle = 'rgba(10,8,24,.72)'; h.rr(c, x, y - hh / 2, w, hh, hh / 2); c.fill(); c.lineWidth = 2 * u; c.strokeStyle = h.COL[side]; c.stroke(); c.restore();\n    const ok = champ === side; h.txt(c, 'SEN\u0130N TAKIMIN: ' + h.NAME[side] + (champ >= 0 ? (ok ? '  \u00b7  \u015eAMP\u0130YON \u2714' : '  \u00b7  2. OLDU') : ''), W / 2, y, 16 * u, ok ? '#ffe14a' : h.COL[side], { w: 800 });\n  }\n\n  /* ---------- sahneler ---------- */\n  function sIntro(c, W, Hh, tm, P) {\n    const h = H(), u = Hh / 540; h.bg(c, W, Hh, '#ffc83a', tm); rays(c, W, Hh, tm, 'rgba(255,200,60,1)', .09);\n    const e = Math.min(1, tm / 1.6), uu = Math.min(Hh * .055, W * .05);\n    h.runner(c, 0, W * (-.1 + .26 * e), Hh * .86, uu, tm * 500, 0, 0); h.runner(c, 1, W * (1.1 - .26 * e), Hh * .86, uu, tm * 500, 0, 1.7);\n    trophy(c, W / 2, Hh * (.74 + (1 - Math.min(1, tm / 1.2)) * .5), Hh * .13, '#fff');\n    h.txt(c, 'TURNUVA F\u0130NAL\u0130', W / 2, Hh * .12, 24 * u, '#ffe14a', { ls: .3, w: 700 }); h.txt(c, 'B\u00dcY\u00dcK F\u0130NAL', W / 2, Hh * .22, Math.min(78 * u, W * .1), '#fff', { glow: '#ffc83a' });\n    h.txt(c, 'MERT  \u2715  EREN', W / 2, Hh * .33, 24 * u, '#dde', { ls: .2 }); h.txt(c, 'Tek tak\u0131m \u015fampiyon olacak', W / 2, Hh * .93, 17 * u, '#cdd', { w: 600 });\n  }\n  function sRecap(c, W, Hh, tm, P) {\n    const h = H(), u = Hh / 540, k = tm - INTRO; h.bg(c, W, Hh, null, tm); h.txt(c, 'YOLUN \u00d6ZET\u0130', W / 2, Hh * .1, 30 * u, '#fff', { ls: .12 });\n    const rows = [['1. HAFTA', 'Sim\u00fclasyon Yar\u0131\u015f\u0131', P.p1], ['2. HAFTA', 'Tak\u0131m Sava\u015f\u0131', P.p2]], cw = Math.min(W * .36, 340 * u), ch = Hh * .3;\n    rows.forEach((r, i) => { const x = W / 2 + (i ? 1 : -1) * (cw / 2 + 16 * u) - cw / 2, y = Hh * .2, show = k > .6 + i * 1.2, w = r[2]; c.save(); c.globalAlpha = show ? 1 : .35; c.fillStyle = w >= 0 && show ? h.COLD[w] : 'rgba(255,255,255,.07)'; h.rr(c, x, y, cw, ch, 18 * u); c.fill(); c.lineWidth = 2 * u; c.strokeStyle = w >= 0 && show ? h.COL[w] : 'rgba(255,255,255,.2)'; c.stroke(); c.restore();\n      h.txt(c, r[0], x + cw / 2, y + 26 * u, 16 * u, '#ffe14a', { ls: .2 }); h.txt(c, r[1], x + cw / 2, y + 50 * u, 14 * u, '#cde', { w: 600 }); h.txt(c, show ? (w >= 0 ? h.NAME[w] : 'BERABERE') : '?', x + cw / 2, y + ch * .72, 40 * u, show ? '#fff' : '#889', show && w >= 0 ? { glow: h.COL[w] } : {}); });\n    if (k > 3.4) { const a = Math.min(1, (k - 3.4) / .6); c.save(); c.globalAlpha = a; h.txt(c, 'TURNUVA SKORU', W / 2, Hh * .6, 16 * u, '#ffe14a', { ls: .25 }); h.txt(c, h.NAME[0] + '  ' + P.pre[0] + '  \u2013  ' + P.pre[1] + '  ' + h.NAME[1], W / 2, Hh * .7, Math.min(58 * u, W * .08), '#fff'); c.restore(); }\n    if (k > 6) { const a = Math.min(1, (k - 6) / .6); c.save(); c.globalAlpha = a; h.txt(c, P.decided ? '\u015eampiyon belli oldu \u2014 t\u00f6ren ba\u015fl\u0131yor!' : 'E\u015fitlik! B\u00fcy\u00fck Final karar verecek', W / 2, Hh * .82, 22 * u, P.decided ? '#7dffa0' : '#ffb25a'); c.restore(); }\n    chip(c, W, Hh, u, results().side, -1, Hh * .93);\n  }\n  function sReveal(c, W, Hh, tm, P) {\n    const h = H(), u = Hh / 540, k = tm - P.reveal; c.fillStyle = '#05030c'; c.fillRect(0, 0, W, Hh);\n    const cw = Math.min(W * .34, 320 * u), ch = Hh * .56, y = Hh * .22, xs = [W * .27 - cw / 2, W * .73 - cw / 2];\n    const ivs = [.35, .35, .4, .45, .5, .6, .75, .9, 1.1], N = ivs.length, sides = []; for (let i = 0; i < N; i++) sides.push((N - 1 - i) % 2 ? 1 - P.champ : P.champ);\n    let tt = 1, spot = -1, fin = false; if (k >= 1) { for (let i = 0; i < N; i++) { if (k < tt + ivs[i]) { spot = sides[i]; break; } tt += ivs[i]; } if (spot < 0) { spot = P.champ; fin = true; } }\n    const landT = 1 + ivs.reduce((a, b) => a + b, 0);\n    h.txt(c, fin ? '\u015eAMP\u0130YON' : '\u015eAMP\u0130YON K\u0130M?', W / 2, Hh * .1, Math.min(52 * u, W * .07), '#fff', { glow: fin ? h.COL[P.champ] : '#fff' });\n    for (let i = 0; i < 2; i++) { const on = spot === i, x = xs[i];\n      if (on) { c.save(); c.globalAlpha = .55; const g = c.createRadialGradient(x + cw / 2, y, 10, x + cw / 2, y + ch, ch * 1.1); g.addColorStop(0