    cells('x', [[33, 35], [34, 35], [34, 36], [34, 39], [33, 39], [23, 35], [23, 39]]).forEach(p => putRect(p[1], p[2], p[3], p[4], 'x'));
    const tc = (c, r) => ({ x: (c + 0.5) * TS, z: (r + 0.5) * TS }); m.tc = tc;
    // oda hücreleri: sınır kutusu, etiket konumu
