      let c0 = 99, r0 = 99, c1 = -1, r1 = -1, sx = 0, sz = 0; for (const [c, r] of cs) { c0 = Math.min(c0, c); r0 = Math.min(r0, r); c1 = Math.max(c1, c); r1 = Math.max(r1, r); sx += c; sz += r; }
      if (!ROOMS[k].rect) ROOMS[k].rect = [c0, r0, c1, r1];
      sx /= cs.length; sz /= cs.length; let best = cs[0], bd = 1e9; for (const q of cs) { const d = (q[0] - sx) ** 2 + (q[1] - sz) ** 2; if (d < bd) { bd = d; best = q; } }
      ROOMS[k].lab = { c: best[0] + 0.5, r: best[1] + 0.5 };
