      const nb4 = [[1, 0], [-1, 0], [0, 1], [0, -1]], wallN = (c, r) => nb4.filter(([dc, dr]) => gch(c + dc, r + dr) === '#').length;
      const doorNear = (c, r, d) => { for (let dr = -d; dr <= d; dr++) for (let dc = -d; dc <= d; dc++) if (gch(c + dc, r + dr) === '.') return true; return false; };
      const pts = [], far = (c, r, d) => pts.every(p => Math.max(Math.abs(p.c - c), Math.abs(p.r - r)) >= d);
      const connected = k => { const cs = cellsOf(k).filter(([c, r]) => grid[r][c] === k); if (!cs.length) return true; const seen = new Set([cs[0][1] * W + cs[0][0]]), st = [cs[0]]; while (st.length) { const [c, r] = st.pop(); for (const [dc, dr] of nb4) { const q = (r + dr) * W + c + dc; if (!seen.has(q) && gch(c + dc, r + dr) === k) { seen.add(q); st.push([c + dc, r + dr]); } } } return seen.size === cs.length; };
      const nearSt = (c, r) => m.STAIRS.some(t => Math.max(Math.abs(t.c - c), Math.abs(t.r - r)) <= 2);
      const rsv = new Set(); for (const k in def.tasks) for (const q of def.tasks[k]) if (q[2] != null) { rsv.add(q[3] * W + q[2]); pts.push({ c: q[2], r: q[3] }); }
      const cand = (k, prio) => cellsOf(k).filter(([c, r]) => grid[r][c] === k && !nearSt(c, r) && !rsv.has(r * W + c)).map(([c, r]) => ({ c, r, p: prio(c, r), h: hh(c, r, k) })).sort((a, b) => a.p - b.p || a.h - b.h);
      const pick = (k, prio, ds, doors) => { const cs = cand(k, prio); for (const dd of doors) for (const d of ds) for (const q of cs) if (!doorNear(q.c, q.r, dd) && far(q.c, q.r, d)) return q; return null; };
      const stPrio = (c, r) => (gch(c, r - 1) === '#' ? 0 : wallN(c, r) ? 1 : 2), vtPrio = (c, r) => (wallN(c, r) >= 2 ? 0 : wallN(c, r) ? 1 : 2), prPrio = (c, r) => (wallN(c, r) >= 2 ? 0 : wallN(c, r) ? 1 : 3);
