  const song = /^builtin:[a-z0-9]{1,12}$/.test(String(e.song)) ? e.song : mediaOk(e.song);
  G.ev = { id: 'e' + Date.now(), name: clean(e.name, 40) || 'Etkinlik', emoji: clean(e.emoji, 4) || '🎉', text: clean(e.text, 120), bg: mediaOk(e.bg), bgType: e.bgType === 'video' ? 'video' : 'img', song, fx: ['none', 'snow', 'confetti', 'stars', 'hearts'].includes(e.fx) ? e.fx : 'none', color: /^#[0-9a-fA-F]{6}$/.test(e.color) ? e.color : '#ffd24a', until: endMs };
